import {
  GET_BOOKINGS_REQUEST,
  GET_BOOKINGS_SUCCESS,
  GET_BOOKINGS_FAILURE,
  GET_DATE_VALUE,
  GET_YEAR_VALUE,
  GET_MONTH_VALUE,
} from "./type"

import dayjs from "dayjs"

const initialState = {
  bookingsData: false,
  error: false,
  requesting: false,
  getYearValue: dayjs(new Date()),
  getMonthValue: dayjs(new Date()),
  getDateValue: dayjs(new Date()),
}

export default (state = initialState, action) => {
  switch (action.type) {
    case GET_BOOKINGS_REQUEST:
      return {
        ...state,
        requesting: true
      }

    case GET_BOOKINGS_SUCCESS:
      return {
        ...state,
        requesting: false,
        bookingsData: action.data
      }
    case GET_BOOKINGS_FAILURE:
      return {
        ...state,
        requesting: false,
        error: action.data
      }
    case GET_YEAR_VALUE:
      return {
        ...state,
        getYearValue: action.data
      }
    case GET_MONTH_VALUE:
      return {
        ...state,
        getMonthValue: action.data
      }
    case GET_DATE_VALUE:
      return {
        ...state,
        getDateValue: action.data
      }

    default:
      return state
  }
}
